package app.yomikai.shell.archive

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.ByteArrayOutputStream
import java.io.File
import java.nio.file.Files
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/**
 * Чтение ZIP без нативной библиотеки проверяется на JVM: от `ZipReader`
 * зависит только [java.nio.channels.FileChannel], то есть подделать дескриптор
 * SAF не нужно. Смысл тестов — ловить тихую порчу страниц: неверное смещение
 * из локального заголовка даёт не ошибку, а JPEG чужой страницы.
 */
class ZipReaderTest {

    private fun zipOf(vararg files: Pair<String, ByteArray>, deflate: Boolean = false): File {
        val file = Files.createTempFile("shell", ".cbz").toFile()
        ZipOutputStream(file.outputStream().buffered()).use { out ->
            files.forEach { (name, bytes) ->
                out.putNextEntry(ZipEntry(name))
                if (deflate) out.write(bytes) else out.write(bytes)
                out.closeEntry()
            }
        }
        return file
    }

    private fun page(seed: Int, size: Int): ByteArray = ByteArray(size) { (it + seed).toByte() }

    @Test
    fun `читает записи без сжатия`() {
        val file = zipOf("001.jpg" to page(1, 4096), "002.jpg" to page(2, 8192))
        val reader = openZip(file.toFileChannel(), file.length())
        reader.use {
            val entries = it.imageEntries(setOf("jpg"))
            assertEquals(listOf("001.jpg", "002.jpg"), entries.map { e -> e.name })
            assertTrue(page(1, 4096).contentEquals(it.read(entries[0])), "байты первой страницы не совпали")
            assertTrue(page(2, 8192).contentEquals(it.read(entries[1])), "байты второй страницы не совпали")
        }
    }

    @Test
    fun `читает записи со сжатием`() {
        val file = zipOf("p/001.png" to page(7, 200_000), deflate = true)
        val reader = openZip(file.toFileChannel(), file.length())
        reader.use {
            val entry = it.find("p/001.png")
            assertTrue(entry != null)
            assertTrue(page(7, 200_000).contentEquals(it.read(entry!!)), "распакованная страница не совпала")
        }
    }

    @Test
    fun `страницы идут в естественном порядке`() {
        val names = listOf("10.jpg", "2.jpg", "1.jpg", "20.jpg", "003.jpg")
        val file = zipOf(*names.map { it to page(1, 16) }.toTypedArray())
        val reader = openZip(file.toFileChannel(), file.length())
        reader.use {
            assertEquals(
                listOf("1.jpg", "003.jpg", "2.jpg", "10.jpg", "20.jpg"),
                it.imageEntries(setOf("jpg")).map { e -> e.name },
            )
        }
    }

    @Test
    fun `главы тайтла сортируются как числа`() {
        val chapters = listOf("Том 10", "том 2", "Том 1")
        assertEquals(
            listOf("Том 1", "том 2", "Том 10"),
            chapters.sortedWith { a, b -> naturalOrder(a, b) },
        )
    }

    @Test
    fun `не zip читается как ошибка`() {
        val file = Files.createTempFile("shell", ".cbr").toFile()
        file.writeBytes(ByteArrayOutputStream().toByteArray())
        file.writeBytes(ByteArray(5000) { 7 })
        assertThrows(java.io.IOException::class.java) {
            openZip(file.toFileChannel(), file.length()).use { it.entries() }
        }
    }

    private fun File.toFileChannel() = java.io.RandomAccessFile(this, "r").channel
}

